  1→package kiro
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→)
  7→
  8→// kiroFileModificationTools lists tool names that create or modify files.
  9→var kiroFileModificationTools = []string{"fs_write", "fs_edit"}
 10→
 11→// parseTranscript unmarshals raw JSON into a kiroTranscript.
 12→// Returns an empty transcript (not an error) for empty or "{}" input,
 13→// matching the placeholder transcript created in IDE mode.
 14→func parseTranscript(data []byte) (*kiroTranscript, error) {
 15→	if len(data) == 0 {
 16→		return &kiroTranscript{}, nil
 17→	}
 18→
 19→	var t kiroTranscript
 20→	if err := json.Unmarshal(data, &t); err != nil {
 21→		return nil, fmt.Errorf("failed to parse kiro transcript: %w", err)
 22→	}
 23→	return &t, nil
 24→}
 25→
 26→// extractUserPrompt tries to extract a prompt string from a user message's
 27→// raw content. Returns "" if the content is a ToolUseResults variant or
 28→// cannot be parsed.
 29→func extractUserPrompt(content json.RawMessage) string {
 30→	if len(content) == 0 {
 31→		return ""
 32→	}
 33→
 34→	var pc kiroPromptContent
 35→	if err := json.Unmarshal(content, &pc); err == nil && pc.Prompt.Prompt != "" {
 36→		return pc.Prompt.Prompt
 37→	}
 38→	return ""
 39→}
 40→
 41→// extractModifiedFilesFromHistory returns deduplicated file paths modified by
 42→// tool calls across the given history entries.
 43→func extractModifiedFilesFromHistory(entries []kiroHistoryEntry) []string {
 44→	seen := make(map[string]bool)
 45→	var files []string
 46→
 47→	for i := range entries {
 48→		for _, path := range extractFilesFromAssistant(entries[i].Assistant) {
 49→			if path != "" && !seen[path] {
 50→				seen[path] = true
 51→				files = append(files, path)
 52→			}
 53→		}
 54→	}
 55→	return files
 56→}
 57→
 58→// extractFilesFromAssistant extracts file paths from an assistant message's
 59→// raw JSON. Returns nil if the message is not a ToolUse variant.
 60→func extractFilesFromAssistant(raw json.RawMessage) []string {
 61→	if len(raw) == 0 {
 62→		return nil
 63→	}
 64→
 65→	var tc kiroToolUseContent
 66→	if err := json.Unmarshal(raw, &tc); err != nil || len(tc.ToolUse.ToolUses) == 0 {
 67→		return nil
 68→	}
 69→
 70→	var paths []string
 71→	for _, call := range tc.ToolUse.ToolUses {
 72→		if !isFileModificationTool(call.Name) {
 73→			continue
 74→		}
 75→		if p := extractFilePath(call.Args); p != "" {
 76→			paths = append(paths, p)
 77→		}
 78→	}
 79→	return paths
 80→}
 81→
 82→// isFileModificationTool reports whether the tool name is a file-modifying tool.
 83→func isFileModificationTool(name string) bool {
 84→	for _, t := range kiroFileModificationTools {
 85→		if name == t {
 86→			return true
 87→		}
 88→	}
 89→	return false
 90→}
 91→
 92→// extractFilePath extracts a file path from tool call args JSON.
 93→// Checks "path", "file_path", and "filename" keys in order.
 94→func extractFilePath(args json.RawMessage) string {
 95→	if len(args) == 0 {
 96→		return ""
 97→	}
 98→
 99→	var m map[string]json.RawMessage
100→	if err := json.Unmarshal(args, &m); err != nil {
101→		return ""
102→	}
103→
104→	for _, key := range []string{"path", "file_path", "filename"} {
105→		raw, ok := m[key]
106→		if !ok {
107→			continue
108→		}
109→		var s string
110→		if err := json.Unmarshal(raw, &s); err == nil && s != "" {
111→			return s
112→		}
113→	}
114→	return ""
115→}
116→
117→// extractLastAssistantResponse walks the history backward and returns the
118→// content of the last Response-type assistant message.
119→func extractLastAssistantResponse(entries []kiroHistoryEntry) string {
120→	for i := len(entries) - 1; i >= 0; i-- {
121→		if len(entries[i].Assistant) == 0 {
122→			continue
123→		}
124→		var rc kiroResponseContent
125→		if err := json.Unmarshal(entries[i].Assistant, &rc); err == nil && rc.Response.Content != "" {
126→			return rc.Response.Content
127→		}
128→	}
129→	return ""
130→}
