164→// --- TranscriptAnalyzer interface implementation ---
165→
166→// GetTranscriptPosition returns the number of history entries in a Kiro transcript.
167→// Kiro uses JSON format with paired user+assistant history entries, so position
168→// is the entry count. Returns 0 if the file doesn't exist, is empty, or is a
169→// placeholder "{}".
170→func (k *KiroAgent) GetTranscriptPosition(path string) (int, error) {
171→	if path == "" {
172→		return 0, nil
173→	}
174→
175→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
176→	if err != nil {
177→		if os.IsNotExist(err) {
178→			return 0, nil
179→		}
180→		return 0, fmt.Errorf("failed to read transcript: %w", err)
181→	}
182→
183→	if len(data) == 0 {
184→		return 0, nil
185→	}
186→
187→	t, err := parseTranscript(data)
188→	if err != nil {
189→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
190→	}
191→
192→	return len(t.History), nil
193→}
194→
195→// ExtractModifiedFilesFromOffset extracts files modified since a given history index.
196→// For Kiro (JSON format), offset is the starting history entry index.
197→func (k *KiroAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
198→	if path == "" {
199→		return nil, 0, nil
200→	}
201→
202→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
203→	if readErr != nil {
204→		if os.IsNotExist(readErr) {
205→			return nil, 0, nil
206→		}
207→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
208→	}
209→
210→	if len(data) == 0 {
211→		return nil, 0, nil
212→	}
213→
214→	t, parseErr := parseTranscript(data)
215→	if parseErr != nil {
216→		return nil, 0, parseErr
217→	}
218→
219→	totalEntries := len(t.History)
220→
221→	if startOffset >= totalEntries {
222→		return nil, totalEntries, nil
223→	}
224→
225→	modifiedFiles := extractModifiedFilesFromHistory(t.History[startOffset:])
226→	return modifiedFiles, totalEntries, nil
227→}
228→
229→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
230→// Only Prompt-type user messages are returned; ToolUseResults entries are skipped.
231→func (k *KiroAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
232→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
233→	if err != nil {
234→		return nil, fmt.Errorf("failed to read transcript: %w", err)
235→	}
236→
237→	t, parseErr := parseTranscript(data)
238→	if parseErr != nil {
239→		return nil, fmt.Errorf("failed to parse transcript: %w", parseErr)
240→	}
241→
242→	var prompts []string
243→	for i := fromOffset; i < len(t.History); i++ {
244→		if prompt := extractUserPrompt(t.History[i].User.Content); prompt != "" {
245→			prompts = append(prompts, prompt)
246→		}
247→	}
248→	return prompts, nil
249→}
250→
251→// ExtractSummary extracts the last assistant response as a session summary.
252→func (k *KiroAgent) ExtractSummary(sessionRef string) (string, error) {
253→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
254→	if err != nil {
255→		return "", fmt.Errorf("failed to read transcript: %w", err)
256→	}
257→
258→	t, parseErr := parseTranscript(data)
259→	if parseErr != nil {
260→		return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
261→	}
262→
263→	return extractLastAssistantResponse(t.History), nil
264→}
