266→// --- SQLite helpers ---
267→
268→// escapeSQLString escapes single quotes for use in SQLite string literals.
269→func escapeSQLString(s string) string {
270→	return strings.ReplaceAll(s, "'", "''")
271→}
272→
273→// --- SQLite session resolution ---
274→
275→// dbPath returns the path to Kiro's SQLite database.
276→func dbPath() (string, error) {
277→	home, err := os.UserHomeDir()
278→	if err != nil {
279→		return "", fmt.Errorf("failed to get home directory: %w", err)
280→	}
281→	switch runtime.GOOS {
282→	case "darwin":
283→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
284→	default: // linux
285→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
286→	}
287→}
288→
289→// querySessionID queries the SQLite database for the most recent conversation ID
290→// associated with the given CWD.
291→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
292→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
293→		return "mock-session-id", nil
294→	}
295→
296→	db, err := dbPath()
297→	if err != nil {
298→		return "", err
299→	}
300→	if _, err := os.Stat(db); err != nil {
301→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
302→	}
303→
304→	query := fmt.Sprintf(
305→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
306→		escapeSQLString(cwd),
307→	)
308→
309→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
310→	out, err := cmd.Output()
311→	if err != nil {
312→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
313→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
314→	}
315→
316→	result := strings.TrimSpace(string(out))
317→	if result == "" || result == "[]" {
318→		return "", nil
319→	}
320→
321→	// sqlite3 -json returns an array of objects
322→	var rows []map[string]string
323→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
324→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
325→	}
326→	if len(rows) == 0 {
327→		return "", nil
328→	}
329→
330→	// The column name from json_extract
331→	for _, v := range rows[0] {
332→		return v, nil
333→	}
334→	return "", nil
335→}
336→
337→// ensureCachedTranscript fetches the conversation from SQLite and caches it
338→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
339→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
340→	repoRoot, err := paths.WorktreeRoot(ctx)
341→	if err != nil {
342→		repoRoot = cwd
343→	}
344→
345→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
346→	cachePath := filepath.Join(cacheDir, sessionID+".json")
347→
348→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
349→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
350→		// In test mode, return the expected cache path without hitting SQLite.
351→		return cachePath, nil
352→	}
353→
354→	db, err := dbPath()
355→	if err != nil {
356→		return "", err
357→	}
358→
359→	query := fmt.Sprintf(
360→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
361→		escapeSQLString(cwd),
362→	)
363→
364→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
365→	out, err := cmd.Output()
366→	if err != nil {
367→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
368→	}
369→
370→	transcript := strings.TrimSpace(string(out))
371→	if transcript == "" {
372→		return "", errors.New("no transcript found")
373→	}
374→
375→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
376→		return "", fmt.Errorf("failed to create cache dir: %w", err)
377→	}
378→
379→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
380→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
381→	}
382→
383→	return cachePath, nil
384→}
