  9→
 10→// testKiroTranscript is a realistic 4-entry Kiro transcript:
 11→//
 12→//	[0] Prompt: "Create a hello.go file" → Response: "I'll create..."
 13→//	[1] Prompt: "Now add a test"         → ToolUse: fs_write /repo/hello.go
 14→//	[2] ToolUseResults                   → ToolUse: fs_write /repo/hello_test.go
 15→//	[3] ToolUseResults                   → Response: "Done! I created both files."
 16→const testKiroTranscript = `{
 17→  "conversation_id": "test-conv-123",
 18→  "history": [
 19→    {
 20→      "user": {"content": {"Prompt": {"prompt": "Create a hello.go file"}}, "timestamp": "2026-01-01T00:00:00Z"},
 21→      "assistant": {"Response": {"message_id": "msg-1", "content": "I'll create that file for you."}}
 22→    },
 23→    {
 24→      "user": {"content": {"Prompt": {"prompt": "Now add a test"}}, "timestamp": "2026-01-01T00:01:00Z"},
 25→      "assistant": {"ToolUse": {"message_id": "msg-2", "tool_uses": [
 26→        {"id": "tu-1", "name": "fs_write", "args": {"path": "/repo/hello.go", "content": "package main"}}
 27→      ]}}
 28→    },
 29→    {
 30→      "user": {"content": {"ToolUseResults": {"tool_use_results": [{"id": "tu-1", "result": "ok"}]}}},
 31→      "assistant": {"ToolUse": {"message_id": "msg-3", "tool_uses": [
 32→        {"id": "tu-2", "name": "fs_write", "args": {"path": "/repo/hello_test.go", "content": "package main"}}
 33→      ]}}
 34→    },
 35→    {
 36→      "user": {"content": {"ToolUseResults": {"tool_use_results": [{"id": "tu-2", "result": "ok"}]}}},
 37→      "assistant": {"Response": {"message_id": "msg-4", "content": "Done! I created both files."}}
 38→    }
 39→  ]
 40→}`
 41→
 42→// --- parseTranscript ---
 43→
 44→func TestParseTranscript(t *testing.T) {
 45→	t.Parallel()
 46→
 47→	tests := []struct {
 48→		name        string
 49→		input       []byte
 50→		wantEntries int
 51→		wantConvID  string
 52→		wantErr     bool
 53→	}{
 54→		{
 55→			name:        "valid transcript",
 56→			input:       []byte(testKiroTranscript),
 57→			wantEntries: 4,
 58→			wantConvID:  "test-conv-123",
 59→		},
 60→		{
 61→			name:        "empty history",
 62→			input:       []byte(`{"conversation_id":"abc","history":[]}`),
 63→			wantEntries: 0,
 64→			wantConvID:  "abc",
 65→		},
 66→		{
 67→			name:        "placeholder {}",
 68→			input:       []byte(`{}`),
 69→			wantEntries: 0,
 70→			wantConvID:  "",
 71→		},
 72→		{
 73→			name:        "empty bytes",
 74→			input:       []byte{},
 75→			wantEntries: 0,
 76→			wantConvID:  "",
 77→		},
 78→		{
 79→			name:    "invalid JSON",
 80→			input:   []byte(`{not json`),
 81→			wantErr: true,
 82→		},
 83→	}
 84→
 85→	for _, tc := range tests {
 86→		t.Run(tc.name, func(t *testing.T) {
 87→			t.Parallel()
 88→			got, err := parseTranscript(tc.input)
 89→			if tc.wantErr {
 90→				if err == nil {
 91→					t.Fatal("expected error, got nil")
 92→				}
 93→				return
 94→			}
 95→			if err != nil {
 96→				t.Fatalf("unexpected error: %v", err)
 97→			}
 98→			if got.ConversationID != tc.wantConvID {
 99→				t.Errorf("ConversationID = %q, want %q", got.ConversationID, tc.wantConvID)
100→			}
101→			if len(got.History) != tc.wantEntries {
102→				t.Errorf("len(History) = %d, want %d", len(got.History), tc.wantEntries)
103→			}
104→		})
105→	}
106→}
107→
108→// --- extractUserPrompt ---
109→
110→func TestExtractUserPrompt(t *testing.T) {
111→	t.Parallel()
112→
113→	tests := []struct {
114→		name string
115→		raw  string
116→		want string
117→	}{
118→		{
119→			name: "Prompt variant",
